def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    if n < 4:
        if last_opp == 'D' and n >= 2:
            return 'D'
        return 'C'

    recent = opp[-10:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_n = len(recent)
    recent_rate = recent_c / recent_n

    if n >= 12:
        if opp_d == 0:
            if n >= 96:
                return 'D' if rng.random() < 0.7 else 'C'
            return 'C'

        tail = opp[-3:]
        if len(tail) >= 2 and all(a == 'D' for a in tail[-2:]):
            if recent_rate < 0.25:
                if rng.random() < 0.10:
                    return 'C'
                return 'D'

    if n >= 96:
        if opp_c > opp_d:
            return 'D' if rng.random() < 0.8 else 'C'
        return 'D'

    if n >= 90:
        if opp_c >= int(0.75 * n) and last_opp == 'C':
            return 'D' if rng.random() < 0.3 else 'C'

    if n >= 15 and recent_rate >= 0.9:
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        streak = 0
        for a in reversed(opp):
            if a == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            if recent_rate > 0.3 or rng.random() < 0.15:
                return 'C'
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        return 'C'

    if n >= 10 and opp_d >= int(0.6 * n):
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if n >= 20 and recent_rate < 0.3:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    return 'C'
